/* A synthetic gaze session, so anyone can see what the results look like without
 * granting camera access or owning a webcam (and so CI can render the view).
 *
 * THIS IS NOT REAL DATA. Every number below was generated by a script, not recorded
 * from a person. It is deliberately plausible rather than random so the UI, the AOI
 * table and the network mapping can be exercised end to end.
 *
 * The UI is REQUIRED to label a demo session as synthetic. `SYNTHETIC.demo` is read by
 * gazelab.js to set that banner, and the same flag is written into the exported JSON so
 * a downloaded file can never be mistaken for a real recording.
 */
export const SYNTHETIC = { demo: true, source: "synthetic fixture, not a recording" };

